<?php
require_once __DIR__.'/departments.php';
require_once __DIR__.'/chrome.php';
require_once __DIR__.'/product-view.php';
function copyText(array $site,string $path): string {$v=$site;foreach(explode('.',$path) as $k)$v=$v[$k]??$path;return '<span data-copy="'.e($path).'">'.e(is_string($v)?$v:$path).'</span>';}
function productCard(array $p,array $site): string {
    $img=$p['images'][0]['thumb']??null;
    $status=$p['stockQuantity']===0?'product.outOfStock':($p['orderable']?'product.availableToOrder':'product.quoteAvailable');
    return '<article class="product-card"><a href="/products/'.e($p['slug']).'"><div class="product-photo">'.($img?'<img loading="lazy" src="'.e($img).'" alt="'.e($p['name']).'">':'<span>'.copyText($site,'product.noPhoto').'</span>').'</div><small class="product-status '.($p['orderable']?'available':'quote').'">'.copyText($site,$status).'</small><h3>'.e($p['name']).'</h3></a><div class="card-bottom"><strong>'.($p['price']!==null?number_format($p['price']).' RWF':copyText($site,'product.askPrice')).'</strong>'.($p['orderable']?'<button type="button" data-add="'.$p['id'].'">'.copyText($site,'product.add').'</button>':'<a class="button secondary" href="/quote?productId='.$p['id'].'">'.copyText($site,$p['inStock']?'product.askPrice':'product.askRestock').'</a>').'</div></article>';
}
function categoryLinks(array $cats,?int $parent=null): string {$h='<ul>';foreach($cats as $c)if($c['parentId']===$parent)$h.='<li><a href="/products?category='.e($c['slug']).'">'.e($c['name']).' <small>'.$c['count'].'</small></a>'.categoryLinks($cats,$c['id']).'</li>';return $h.'</ul>';}
function renderPage(string $path): void {
    $site=siteContent();$cats=categories();$admin=str_starts_with($path,'/admin');$known=['/','/about','/products','/cart','/checkout','/quote','/signin','/signup','/account','/admin','/admin/products','/admin/categories','/admin/customers','/admin/quotes','/admin/chat','/admin/whatsapp','/admin/site-content','/admin/login'];$product=null;
    if($path==='/admin/login'){header('Location: /signin',true,302);return;}
    if(preg_match('~^/products/([^/]+)$~',$path,$m)){$p=one(PRODUCT_SQL.' WHERE p.slug=? AND p.is_active=1',[$m[1]]);if(!$p||!in_array((int)$p['category_id'],visibleIds(rows('SELECT * FROM categories')),true))fail('Product not found.',404);$product=mapProduct($p);}
    elseif(!in_array($path,$known,true)&&!preg_match('~^/order/[A-Za-z0-9_-]{16,64}$~',$path))fail('Page not found.',404);
    $title=$product?$product['name']:($path==='/'?'Bathroom, plumbing and water equipment':ucwords(str_replace(['/','-'],[' ',' '],$path)));$desc=$product?$product['summary']:$site['about']['intro'];header('Content-Type: text/html; charset=utf-8');if($admin||in_array($path,['/account','/checkout','/cart'],true)||str_starts_with($path,'/order/'))header('Cache-Control: private, no-store');
    ?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title><?=e($title)?> | <?=e($site['business']['name'])?></title><meta name="description" content="<?=e($desc)?>"><?php if($admin||str_starts_with($path,'/order/')||in_array($path,['/account','/cart','/checkout','/signin','/signup'],true)):?><meta name="robots" content="noindex,nofollow"><?php endif;?><link rel="icon" href="/favicon.png"><link rel="stylesheet" href="/assets/app.css"><link rel="stylesheet" href="/assets/storefront.css"><link rel="stylesheet" href="/assets/chrome.css"><link rel="stylesheet" href="/assets/pages.css"><link rel="stylesheet" href="/assets/payments.css"><script type="module" src="/assets/departments.js"></script><script type="module" src="/assets/app.js"></script></head><body data-page="<?=e($path)?>"><a class="skip" href="#main">Skip to content</a>
    <div class="store-header">
    <div class="store-utility"><div class="wrap"><a href="tel:<?=e(preg_replace('/[^+0-9]/','',$site['business']['tel']))?>">Call us: <?=copyText($site,'business.tel')?></a><span class="header-location">Serving Africa, especially Rwanda</span><div class="header-preferences"><?php renderPreferences();?></div></div></div>
    <header class="store-head"><a class="brand" href="/" aria-label="MATTE home"><img class="logo brand-light" src="<?=e($site['branding']['logoUrl'])?>" alt="MATTE"><img class="logo brand-dark" src="<?=e($site['branding']['lightLogoUrl']??$site['branding']['logoUrl'])?>" alt="MATTE"></a><form action="/products" class="search" role="search"><input type="search" name="q" aria-label="Search all products" placeholder="<?=e($site['home']['searchPlaceholder'])?>" value="<?=e($_GET['q']??'')?>"><button>Search</button></form><div class="header-actions"><a id="account-link" href="/signin"><?=copyText($site,'navigation.signIn')?></a><a class="header-signup button" href="/signup">Sign up</a><button class="plain header-chat" type="button">Chat with us</button><a href="/cart"><?=copyText($site,'navigation.cart')?> <span id="cart-count">0</span></a><button class="plain" id="signout" hidden>Sign out</button></div></header>
    <?php if(!$admin)renderDepartments($cats,$site);?>
    </div>
    <main id="main" class="wrap">
    <?php if($admin):?><div class="admin-shell"><?php renderAdminNav($path);?><section id="admin-content" aria-live="polite"><p>Loading administration…</p></section></div>
    <?php elseif($path==='/'): $featured=listProducts(['featured'=>'1','limit'=>8]);$hero=$featured[0]['images'][0]['url']??'/category-samples/sanitaryware.webp';?>
    <section class="hero"><div><p class="eyebrow"><?=copyText($site,'home.heroEyebrow')?></p><h1><?=copyText($site,'home.heroTitle')?></h1><p><?=copyText($site,'home.heroDescription')?></p><form action="/products" class="hero-search" role="search"><input type="search" name="q" aria-label="Search products" placeholder="<?=e($site['home']['searchPlaceholder'])?>"><button>Search</button></form><div class="department-chips"><?php foreach(array_slice(departmentChildren($cats),0,5) as $chip):?><a href="/products?category=<?=e($chip['slug'])?>"><?=e($chip['name'])?></a><?php endforeach;?></div><p class="assurances"><?=copyText($site,'home.assuranceOne')?> · <?=copyText($site,'home.assuranceTwo')?></p></div><a class="hero-photo" href="/products/<?=e($featured[0]['slug']??'')?>"><img src="<?=e($hero)?>" alt="<?=e($featured[0]['name']??'MATTE bathroom and water equipment')?>"><span class="hero-caption"><small><?=copyText($site,'home.featureEyebrow')?></small><strong><?=e($featured[0]['name']??$site['home']['featureFallback'])?></strong><span><?=copyText($site,'home.exploreProducts')?> &rarr;</span></span></a></section>
    <section><p class="eyebrow"><?=copyText($site,'home.departmentsEyebrow')?></p><div class="section-heading"><h2><?=copyText($site,'home.departmentsTitle')?></h2><a href="/products"><?=copyText($site,'home.allDepartments')?> ↗</a></div><div class="category-grid"><?php foreach($cats as $c):if($c['parentId']!==null)continue;?><a class="category-card" href="/products?category=<?=e($c['slug'])?>"><img loading="lazy" src="<?=e(departmentSample($c))?>" alt=""><h3><?=e($c['name'])?></h3><small><?=$c['count']?> products</small></a><?php endforeach;?></div></section>
    <?php foreach($cats as $c):if($c['parentId']!==null||!$c['count'])continue; $rail=listProducts(['category'=>$c['slug'],'page'=>1,'pageSize'=>24]);?><section class="home-department" data-category="<?=e($c['slug'])?>"><div class="section-heading"><div><p class="eyebrow">Shop by department</p><h2><?=e($c['name'])?></h2><p class="rail-hint">Swipe or use the arrows to browse <?=$c['count']?> products.</p></div><div class="rail-actions"><a href="/products?category=<?=e($c['slug'])?>">View all</a><button class="secondary" data-rail-move="-1" aria-label="Previous <?=e($c['name'])?> products">&larr;</button><button class="secondary" data-rail-move="1" aria-label="Next <?=e($c['name'])?> products">&rarr;</button></div></div><div class="home-product-rail" tabindex="0" role="region" aria-label="<?=e($c['name'])?> product carousel"><?php foreach($rail['items'] as $p)echo productCard($p,$site);?><?php if($rail['totalPages']>1):?><div class="rail-more"><button data-rail-more data-page="1">Load more products</button><p role="status"></p></div><?php endif;?></div></section><?php endforeach;?>
    <section><p class="eyebrow"><?=copyText($site,'home.productsEyebrow')?></p><div class="section-heading"><h2><?=copyText($site,'home.productsTitle')?></h2><a href="/products"><?=copyText($site,'home.browseProducts')?> ↗</a></div><div class="product-grid"><?php foreach($featured as $p)echo productCard($p,$site);?></div></section>
    <section class="story"><p class="eyebrow"><?=copyText($site,'home.storyEyebrow')?></p><h2><?=copyText($site,'home.storyTitle')?></h2><p><?=copyText($site,'home.storyBody')?></p></section><section><h2><?=copyText($site,'home.stepsTitle')?></h2><div class="three-cols"><?php foreach($site['home']['steps'] as $i=>$step):?><article><span class="step-number">0<?=$i+1?></span><h3><?=copyText($site,'home.steps.'.$i.'.title')?></h3><p><?=copyText($site,'home.steps.'.$i.'.description')?></p></article><?php endforeach;?></div></section><section class="cta"><h2><?=copyText($site,'home.ctaTitle')?></h2><p><?=copyText($site,'home.ctaBody')?></p><a class="button" href="https://wa.me/<?=e(preg_replace('/\D/','',$site['business']['whatsappNumber']))?>"><?=copyText($site,'home.ctaButton')?></a></section>
    <?php elseif($path==='/about'):?><section class="prose about-page"><p class="eyebrow"><?=copyText($site,'about.navLabel')?></p><h1><?=copyText($site,'about.title')?></h1><p class="lead"><?=copyText($site,'about.intro')?></p><div class="about-sections"><?php foreach(['story','mission','values'] as $k):?><section><h2><?=copyText($site,'about.'.$k.'Title')?></h2><p><?=copyText($site,'about.'.$k.'Body')?></p></section><?php endforeach;?></div></section>
    <?php elseif($path==='/products'): $q=[...$_GET,'page'=>$_GET['page']??1];$listing=listProducts($q);$selectedCategory=null;foreach($cats as $c)if($c['slug']===($_GET['category']??''))$selectedCategory=$c;?>
    <section><div class="catalog-layout"><aside><?php renderCatalogTree($cats,(string)($_GET['category']??''));?><form id="filters" method="get"><input type="hidden" name="category" value="<?=e($_GET['category']??'')?>"><input type="hidden" name="q" value="<?=e($_GET['q']??'')?>"><label><?=copyText($site,'catalog.sort')?><select name="sort"><?php foreach(['featured'=>'Featured','price_asc'=>'Price: low to high','price_desc'=>'Price: high to low','name'=>'Name'] as $k=>$v):?><option value="<?=$k?>" <?=($_GET['sort']??'')===$k?'selected':''?>><?=e($v)?></option><?php endforeach;?></select></label><label>Availability<select name="availability"><option value="">All</option><option value="in" <?=($_GET['availability']??'')==='in'?'selected':''?>>In stock</option><option value="out" <?=($_GET['availability']??'')==='out'?'selected':''?>>Out of stock</option></select></label><?php foreach($listing['facets'] as $facet):?><fieldset><legend><?=e($facet['name'])?></legend><?php foreach($facet['values'] as $v):$value=$facet['name'].':'.$v['value'];?><label class="check"><input type="checkbox" name="facet[]" value="<?=e($value)?>" <?=in_array($value,(array)($_GET['facet']??[]),true)?'checked':''?>><?=e($v['value'])?> (<?=$v['count']?>)</label><?php endforeach;?></fieldset><?php endforeach;?><button>Apply filters</button><a href="/products"><?=copyText($site,'catalog.clearFilters')?></a></form><h3><?=copyText($site,'catalog.projectTitle')?></h3><p><?=copyText($site,'catalog.projectBody')?></p><a href="/quote"><?=copyText($site,'catalog.quoteButton')?></a></aside><div><div class="catalog-heading"><h1><?=!empty($_GET['q'])?'Results for '.e($_GET['q']):($selectedCategory?e($selectedCategory['name']):copyText($site,'catalog.allProducts'))?></h1><p><?=$listing['total']?> products</p></div><nav class="category-children" aria-label="Subcategories"><?php foreach(departmentChildren($cats,$selectedCategory['id']??null) as $child):?><a class="category-tile" href="/products?category=<?=e($child['slug'])?>"><img src="<?=e(departmentSample($child))?>" alt="" loading="lazy"><span><?=e($child['name'])?></span></a><?php endforeach;?></nav><div class="catalog-callout"><div><strong><?=copyText($site,'catalog.projectTitle')?></strong><p><?=copyText($site,'catalog.projectBody')?></p></div><a class="button" href="/quote"><?=copyText($site,'catalog.quoteButton')?></a></div><div class="product-grid"><?php foreach($listing['items'] as $p)echo productCard($p,$site);if(!$listing['items'])echo copyText($site,'catalog.noResults');?></div><nav class="pagination"><?php for($i=max(1,$listing['page']-2);$i<=min($listing['totalPages'],$listing['page']+2);$i++):?><a class="button secondary <?=$i===$listing['page']?'selected':''?>" href="?<?=e(http_build_query([...$_GET,'page'=>$i]))?>"><?=$i?></a><?php endfor;?></nav></div></div></section>
    <?php elseif($product):renderProduct($product,$site);?>
    <?php else:?><section id="app-content" aria-live="polite"><p>Loading…</p></section><?php endif;?>
    </main><?php if(!$admin)renderFooter($site,$cats);?>
    <?php if(!$admin):?><a class="whatsapp-float" href="https://wa.me/<?=e(preg_replace('/\D/','',$site['business']['whatsappNumber']))?>" target="_blank" rel="noopener">Chat on WhatsApp</a><button id="chat-toggle" class="chat-toggle"><span class="chat-monogram" aria-hidden="true">M</span> Chat</button><aside id="chat-panel" class="chat-panel" hidden><div class="section-heading"><h3>MATTE chat</h3><button id="chat-close" class="plain" aria-label="Close chat">×</button></div><form id="chat-identify"><input name="name" placeholder="Your name" aria-label="Your name"><input name="phone" placeholder="Phone" aria-label="Phone"><button>Save contact</button></form><div id="chat-messages" class="messages"></div><small id="chat-typing"></small><form id="chat-send"><textarea name="body" maxlength="2000" required aria-label="Message" placeholder="How can we help?"></textarea><button>Send</button></form><p class="error" id="chat-error"></p></aside><?php endif;?>
    <div id="toast" role="status" hidden></div><dialog id="modal"><button class="plain close-modal" aria-label="Close">×</button><div id="modal-content"></div></dialog></body></html><?php
}
